mapper.update:
UPDATE pcd_im_call_record
status = #{status}, end_time = #{endTime}, duration = #{duration}, reject_reason = #{rejectReason}, participants = #{participants}, video_enabled = #{videoEnabled}, screen_share_enabled = #{screenShareEnabled}, hangup_by = #{hangupBy}, update_time = NOW()
WHERE call_id = #{callId}

mapper.select:
SELECT * FROM pcd_im_call_record
WHERE caller_id = #{userId} OR callee_id = #{userId}
   OR JSON_CONTAINS(participants, JSON_QUOTE(#{userId}))
ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM pcd_im_call_record
WHERE caller_id = #{userId} OR callee_id = #{userId}
   OR JSON_CONTAINS(participants, JSON_QUOTE(#{userId}))

SELECT * FROM pcd_im_call_record
WHERE (caller_id = #{userId} OR callee_id = #{userId}
       OR JSON_CONTAINS(participants, JSON_QUOTE(#{userId})))
  AND create_time BETWEEN #{startTime} AND #{endTime}
ORDER BY create_time DESC
